mapper:

    /* com.heeji.picket.repository.PostRepository.list */
    SELECT  *
    FROM    POST
    WHERE   1 = 1
    AND     TYPE = #{type}



    /* com.heeji.picket.repository.PostRepository.info */
    SELECT  *
    FROM    POST
    WHERE   1 = 1
    AND     POST_ID = #{postId}



    UPDATE POST SET HITS = HITS + 1 WHERE POST_ID = #{postId}


int insert(Map params);

int update(Map params);

int delete(Map params);
